/// <summary>
///     The <c>AVAPriceDiscGroup_PriceDiscGroupDs_Extension</c> class is the extension for <c>PriceDiscGroup</c>
/// </summary>
[ExtensionOf(formDataSourceStr(PriceDiscGroup, PriceDiscGroup))]
final class AVAPriceDiscGroup_PriceDiscGroupDs_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>active</c> method.
///     AVA - Schneider 15.05.2024
/// </summary>
/// <returns>
///     <c>int</c> as return value
/// </returns>
public int active()
{
    int                 retVal;

    FormDataSource      locFormDataSource;
    PriceDiscGroup      locPriceDiscGroup;
    FormCheckBoxControl locFormCheckBoxControl;

    retVal                  = next active();

    locFormDataSource       = element.PriceDiscGroup_DS;
    locPriceDiscGroup       = locFormDataSource.cursor();
    locFormCheckBoxControl  = element.PriceDiscGroup_AVAPriceInceaseComplete;

    if(     locPriceDiscGroup.Type      == PriceGroupType::PriceGroup
        &&  locPriceDiscGroup.Module    == ModuleInventCustVend::Cust   )
    {
        locFormCheckBoxControl.allowEdit(true);
    }
    else
    {
        locFormCheckBoxControl.allowEdit(false);
    }

    return retVal;
}
